def choose(path, routes, fallback):
    if path in routes:
        return routes[path]
    matches = [key for key in routes if path.startswith(key.rstrip('/') + '/')]
    return routes[max(matches, key=len)] if matches else fallback

def mount(path, routes):
    if path in routes: return path
    found = [key for key in routes if path.startswith(key.rstrip('/') + '/')]
    return max(found, key=len) if found else None
